export class AccountWorkspace{
 constructor(h){this.h=h;this.user=null;this.menu=false;this.available=false;this.busy=false;}
 async request(path,body){const response=await fetch('/v1/auth/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',redirect:'error',headers:{'X-ArtiCheck-Client':'review-api',...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(12000)});let value;try{value=await response.json();}catch{throw Error('账户服务暂不可用，请稍后重试。');}if(!response.ok)throw Error(value.error?.message||'账户操作未完成。');return value;}
 async init(){try{this.user=(await this.request('me')).user;this.available=true;}catch{}this.bind();}
 topbar(){const e=this.h.esc;if(!this.user)return `<button class="btn account-login" data-account="login">登录 / 注册</button>`;return `<div class="account-control"><button class="account-trigger" data-account="menu" aria-haspopup="menu" aria-expanded="${this.menu}" aria-label="${e(this.user.name)}的账户菜单"><span class="account-avatar">${e([...this.user.name][0].toUpperCase())}</span><span>${e(this.user.name)}</span>${this.h.icon('down')}</button>${this.menu?`<div class="account-menu" role="menu"><div><strong>${e(this.user.name)}</strong><small>@${e(this.user.username)}</small></div><button role="menuitem" data-account="center">${this.h.icon('settings')}个人中心</button><button role="menuitem" data-account="new">${this.h.icon('plus')}新建审查</button><button role="menuitem" data-account="logout">${this.h.icon('logout')}退出登录</button></div>`:''}</div>`;}
 open(mode='login',username=''){
  this.mode=mode;const register=mode==='register',e=this.h.esc;
  this.h.modal(register?'创建 ArtiCheck 账户':'登录 ArtiCheck',`<div class="account-auth"><aside><img src="./mark.svg" alt=""><strong>从论文主张<br>走到可核查证据。</strong><p>登录后，以账户身份提交审查、保存报告与追踪执行。</p><small>论文和源码留在当前浏览器，服务器审查记录按账户隔离。</small></aside><form id="account-form" class="account-form"><div class="account-auth-tabs" role="tablist" aria-label="账户操作"><button type="button" role="tab" aria-selected="${!register}" data-account="login">登录</button><button type="button" role="tab" aria-selected="${register}" data-account="register">注册</button></div>${register?'<label for="account-name">显示名称</label><input id="account-name" name="name" autocomplete="nickname" maxlength="40" required>':''}<label for="account-username">用户名</label><input id="account-username" name="username" autocomplete="username" autocapitalize="none" spellcheck="false" pattern="[a-zA-Z0-9_]{3,32}" minlength="3" maxlength="32" value="${e(username)}" aria-describedby="account-username-hint" required><small id="account-username-hint">3–32 位字母、数字或下划线</small><label for="account-password">密码</label><div class="account-password"><input id="account-password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="12" maxlength="128" aria-describedby="account-password-hint" required><button type="button" data-account="show-password" aria-label="显示密码">显示</button></div><small id="account-password-hint">12–128 个字符，建议使用密码管理器</small>${register?'<label for="account-password-confirm">再次输入密码</label><input id="account-password-confirm" name="confirm" type="password" autocomplete="new-password" minlength="12" maxlength="128" required>':''}<p class="account-form-error" role="alert" id="account-error"></p><button class="btn primary account-submit" type="submit">${register?'创建账户':'登录'}</button><p class="account-auth-note">账户登录与网站审阅访问码分别验证，调用费用受全站预算控制。</p></form></div>`,'',true);
  document.querySelector('#account-name,#account-username')?.focus();
 }
 projects(){return this.h.projects().filter(p=>(p.online_account||null)===(this.user?.id||null));}
 center(){const e=this.h.esc,u=this.user;if(!u)return `<section class="online-empty"><h2>登录后管理审查身份</h2><p>创建账户或登录已有账户，查看个人资料与当前浏览器的审查项目。</p><button class="btn primary" data-account="login">登录 / 注册</button></section>`;const projects=this.projects(),reports=projects.filter(p=>p.online_report?.review),executed=reports.filter(p=>p.online_report?.execution_performed||p.online_report?.execution?.execution_performed);
 return `<div class="account-center"><section class="account-overview"><span class="account-avatar large">${e([...u.name][0].toUpperCase())}</span><div><h2>${e(u.name)}</h2><p>@${e(u.username)} · ${e(u.created_at.slice(0,10))} 加入</p></div><button class="btn" data-account="new">${this.h.icon('plus')}新建审查</button></section><div class="account-counts"><div><span>当前浏览器项目</span><strong>${projects.length}</strong></div><div><span>已有审查报告</span><strong>${reports.length}</strong></div><div><span>包含实际执行</span><strong>${executed.length}</strong></div></div><div class="account-settings"><section><h2>个人资料</h2><p>显示名称用于头像与审查工作空间。</p></section><form data-account-form="profile"><label for="profile-name">显示名称</label><input id="profile-name" name="name" value="${e(u.name)}" maxlength="40" required><label>用户名</label><p class="account-readonly">@${e(u.username)}</p><p role="status" class="account-result"></p><button class="btn" type="submit">保存资料</button></form><section><h2>账户安全</h2><p>修改密码会使其他设备的登录状态失效。</p></section><form data-account-form="password"><label for="current-password">当前密码</label><input id="current-password" name="current_password" type="password" autocomplete="current-password" minlength="12" maxlength="128" required><label for="new-password">新密码</label><input id="new-password" name="new_password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><small>12–128 个字符</small><p role="status" class="account-result"></p><button class="btn" type="submit">更新密码</button></form></div><section class="account-projects"><div class="online-section-heading"><h2>最近审查</h2><span>当前浏览器 · ${projects.length} 项</span></div>${projects.length?projects.slice(0,6).map(p=>`<button data-account-project="${e(p.id)}"><span><strong>${e(p.title||p.paper?.name||p.repository?.name||'未命名审查')}</strong><small>${p.online_report?.review?'已有报告':p.online_pending_request?'审查处理中':'材料准备中'}</small></span>${this.h.icon('chevron')}</button>`).join(''):'<p class="online-notice">还没有该账户的项目，从新建审查开始。</p>'}<p class="online-footnote">原始论文、源码与项目列表保存在当前浏览器，不自动跨设备同步。服务器审查报告保留 7 天；账户资料与登录会话不包含上传材料。</p></section></div>`;
 }
 async changed(user){this.user=user;this.menu=false;await this.h.changed?.();this.h.render();}
 bind(){
  document.addEventListener('click',async event=>{
   const t=event.target.closest('[data-account]');
   if(!t){if(this.menu&&!event.target.closest('.account-control')){this.menu=false;this.h.render();}const row=event.target.closest('[data-account-project]');if(row)this.h.openProject(row.dataset.accountProject);return;}
   const action=t.dataset.account;
   if(!this.h.canSwitch()&&['login','register','logout','new'].includes(action)){this.h.toast('请等待当前审查操作结束后再切换账户。');return;}
   if(action==='menu'){this.menu=!this.menu;this.h.render();if(this.menu)document.querySelector('.account-menu button')?.focus();return;}
   if(action==='login'||action==='register'){this.open(action,document.querySelector('#account-username')?.value||'');return;}
   if(action==='show-password'){const input=document.querySelector('#account-password');input.type=input.type==='password'?'text':'password';t.textContent=input.type==='password'?'显示':'隐藏';t.setAttribute('aria-label',input.type==='password'?'显示密码':'隐藏密码');return;}
   if(action==='center'){this.menu=false;this.h.navigate('account');return;}
   if(action==='new'){this.menu=false;await this.h.newReview();return;}
   if(action==='logout'){t.disabled=true;try{await this.request('logout',{});await this.changed(null);this.h.toast('已退出登录');}catch(error){this.h.toast(error.message);t.disabled=false;}}
  });
  document.addEventListener('keydown',event=>{if(this.menu&&event.key==='Escape'){this.menu=false;this.h.render();document.querySelector('.account-trigger')?.focus();}if(this.menu&&['ArrowDown','ArrowUp'].includes(event.key)){const buttons=[...document.querySelectorAll('.account-menu button')],i=buttons.indexOf(document.activeElement);buttons[(i+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();event.preventDefault();}});
  document.addEventListener('submit',async event=>{
   const form=event.target;if(!form.matches('#account-form,[data-account-form]'))return;event.preventDefault();if(this.busy||!form.reportValidity())return;if(!this.h.canSwitch()){this.h.toast('请等待当前审查结束后再操作账户。');return;}
   const data=Object.fromEntries(new FormData(form)),auth=form.id==='account-form',errorNode=form.querySelector('#account-error,.account-result'),button=form.querySelector('[type=submit]');
   if(auth&&this.mode==='register'&&data.password!==data.confirm){errorNode.textContent='两次输入的密码不一致。';document.querySelector('#account-password-confirm')?.focus();return;}
   this.busy=true;button.disabled=true;const label=button.textContent;button.textContent='正在提交…';errorNode.textContent='';
   try{const result=await this.request(auth?this.mode:form.dataset.accountForm,data);if(auth){this.h.closeModal();await this.changed(result.user);this.h.toast(this.mode==='register'?'账户已创建并登录':'已登录');}else{this.user=result.user;errorNode.textContent='已保存';this.h.render();this.h.toast(form.dataset.accountForm==='password'?'密码已更新，其他登录会话已失效':'资料已保存');}}
   catch(error){errorNode.textContent=error.message;errorNode.classList.add('failed');}
   finally{this.busy=false;button.disabled=false;button.textContent=label;if(auth)for(const input of form.querySelectorAll('[type=password]'))input.value='';}
  });
 }
}
